# Strategy: Find each language section by looking for its known unique marker
# Each language has a section header comment like "// ENGLISH (en)" or "// TELUGU (te)"
# Then find the last key (game_diff_advanced) in that section and append after it

LANG_ORDER = ['en', 'te', 'ta', 'kn', 'ml', 'hi']
LANG_NAMES = {
    'en': 'ENGLISH',
    'te': 'TELUGU', 
    'ta': 'TAMIL',
    'kn': 'KANNADA',
    'ml': 'MALAYALAM',
    'hi': 'HINDI'
}

def escape_ts_str(s):
    return s.replace('\\', '\\\\').replace('"', '\\"')

def build_new_entries(lang):
    lines = []
    for key, vals in TRANSLATIONS.items():
        val = vals.get(lang, vals.get('en', ''))
        lines.append(f'        {key}: "{escape_ts_str(val)}"')
    return ',\n'.join(lines)

# Process each language
for lang in LANG_ORDER:
    # Find the lang section start
    lang_name = LANG_NAMES[lang]
    section_marker = f'// {lang_name} ({lang})'
    
    section_start = content.find(section_marker)
    if section_start == -1:
        print(f"ERROR: Could not find section marker for {lang}: '{section_marker}'")
        continue
    
    # Find the next language section (to bound our search)
    next_lang_idx = LANG_ORDER.index(lang) + 1
    if next_lang_idx < len(LANG_ORDER):
        next_lang = LANG_ORDER[next_lang_idx]
        next_marker = f'// {LANG_NAMES[next_lang]} ({next_lang})'
        section_end = content.find(next_marker, section_start)
        if section_end == -1:
            section_end = len(content)
    else:
        section_end = len(content)
    
    # Within the section, find "game_diff_advanced" followed by its value
    section_content = content[section_start:section_end]
    
    # Find game_diff_advanced line
    gda_pattern = r'game_diff_advanced:\s*"[^"]*"'
    m = re.search(gda_pattern, section_content)
    if not m:
        print(f"ERROR: Could not find game_diff_advanced in section for lang {lang}")
        continue
    
    # Insert after the game_diff_advanced line  
    insert_offset = section_start + m.end()
    new_entries = build_new_entries(lang)
    
    content = content[:insert_offset] + ',\n' + new_entries + content[insert_offset:]
    print(f"OK: {lang} - {len(TRANSLATIONS)} entries added")

# Write file
with open('src/utils/translations.ts', 'w', encoding='utf-8') as f:
    f.write(content)

print("\nDONE: translations.ts updated successfully")
print(f"File size: {len(content)} bytes")
